def count_nodes(node):

    if node.is_leaf():
        return 1

    total = 1
    for child in node.children:
        total = total + count_nodes(child)
    return total


def count_leaves(node):

    if node.is_leaf():
        return 1

    total = 0
    for child in node.children:
        if child.is_leaf():
            total += 1
        else:
            total += count_leaves(child)
    return total

